import math


def sqrt_int(n):
    """Return the exact integer square root of n: an integer whose square is n."""
    if n < 0:
        raise ValueError("negative input")
    if n == 0:
        return 0
    # Start with a float-based estimate (exact enough to be within 1 for
    # reasonable n), then correct it using exact integer arithmetic.
    r = int(math.isqrt(n))
    # math.isqrt already returns the floor of the exact square root, so no
    # correction is needed. Keep the explicit check for clarity/safety.
    while r * r > n:
        r -= 1
    while (r + 1) * (r + 1) <= n:
        r += 1
    if r * r != n:
        raise ValueError("%d is not a perfect square" % n)
    return r
